// 正常期间检查
int check_normal(int i)
{
	// S[i] <= 0，即为错误值
	if (s[i] <= 0) return FALSE;

	// 和前面采样数据比较的前提条件是：前面的采样数据必须是正常状态，或者正常期错误状态
	if (i >= 1 && (status[i - 1] == NORMAL || status[i - 1] == FAULT))
