	}

	return TRUE; // 其它情况为正常值
}

// 故障恢复期检查
int check_recovery(int i)
{
	// S[i] <= 0，即为错误值
	if (s[i] <= 0) return FALSE;

	// 和前面采样数据比较的前提条件是：前面的采样数据不能时丢弃状态，以及恢复期错误状态
	if (i >= 1 && status[i - 1] != ABORT && status[i - 1] != RECOVERY_FAULT)
